  "code": "def rule_phmsa_notice_signatory(doc: dict) -> list[dict]:\n    try:\n        lines = doc.get(\"lines\") or []\n        if not lines:\n            return []\n\n        def norm(text: str) -> str:\n            text = (text or \"\").lower()\n            out = []\n            last_space = False\n            for ch in text:\n                if ch.isalnum():\n                    out.append(ch)\n                    last_space = False\n                else:\n                    if not last_space:\n                        out.append(\" \")\n                        last_space = True\n            return \" \".join(\"\".join(out).split())\n\n        def is_closing_cue(text: str) -> bool:\n            n = norm(text)\n            return (\n                \"sincerely\" in n\n                or \"signed by\" in n\n                or \"digitally signed by\" in n\n                or n == \"for\"\n            )\n\n        aliases = [\n            \"gregory alan ochs\",\n            \"gregory a ochs\",\n            \"gregory ochs\",\n            \"a ochs\",\n            \"dustin b hubbard\",\n            \"dustin hubbard\",\n            \"robert thomas burrough\",\n            \"robert burrough\",\n            \"mary louise mcdaniel\",\n            \"mary l mcdaniel p e\",\n            \"mary l mcdaniel\",\n            \"mary mcdaniel p e\",\n            \"mary mcdaniel\",\n            \"bryan jeffery lethcoe\",\n            \"bryan lethcoe\",\n            \"david a barrett\",\n            \"david barrett\",\n            \"james a urisko\",\n            \"james urisko\",\n        ]\n\n        results = []\n        seen = set()\n\n        for idx, line in enumerate(lines):\n            text = line.get(\"text\") or \"\"\n            ntext = norm(text)\n            if not ntext:\n                continue\n\n            alias_hit = None\n            for alias in aliases:\n                if alias in ntext:\n                    alias_hit = alias\n                    break\n            if alias_hit is None:\n                continue\n\n            window_start = max(0, idx - 4)\n            window = lines[window_start:idx]\n            if not any(is_closing_cue(prev.get(\"text\") or \"\") for prev in window):\n                continue\n\n            key = (\n                line.get(\"page_no\"),\n                line.get(\"line_no\"),\n                norm(text),\n            )\n            if key in seen:\n                continue\n            seen.add(key)\n\n            span = {\"text\": text}\n            if \"page_no\" in line:\n                span[\"page_no\"] = line.get(\"page_no\")\n            if \"line_no\" in line:\n                span[\"line_no\"] = line.get(\"line_no\")\n            results.append(span)\n\n        return results\n    except Exception:\n        return []\n",
